        "outputs": [
          ["clean_text", "string"]
        ],
        "code": "import re\n\ndef main(html: str):\n\tif not html:\n\t\treturn {\"clean_text\": \"\"}\n\t# remove script and style blocks\n\thtml = re.sub(r\"<script[\\s\\S]*?</script>\", \" \", html, flags=re.IGNORECASE)\n\thtml = re.sub(r\"<style[\\s\\S]*?</style>\", \" \", html, flags=re.IGNORECASE)\n\t# remove all HTML tags\n\ttext = re.sub(r\"<[^>]+>\", \" \", html)\n\t# convert HTML entities roughly\n\ttext = text.replace(\"&nbsp;\", \" \").replace(\"&amp;\", \"&\").replace(\"&lt;\", \"<\").replace(\"&gt;\", \">\")\n\t# collapse whitespace\n\ttext = re.sub(r\"\\s+\", \" \", text).strip()\n\treturn {\"clean_text\": text}"
      }
    },
    {
      "id": "4",
      "type": "question-classifier",
      "param": {
        "query_variable_selector": ["platform", "1"],
        "classes": [
          "Instagram",
          "X",
          "Xiaohongshu",
          "WeChat Official Account"
        ]
      }
    },
