      }
    },
    {
      "id": "5",
      "type": "iteration",
      "param": {
        "iterator_selector": ["queries", "4"],
        "output_selector": ["section_text", "5-4"]
      }
    },
    {
      "id": "5-1",
      "type": "iteration-start",
      "param": {}
    },
    {
      "id": "5-2",
      "type": "google-search",
      "param": {
        "query": "{{#'5'.item#}}"
      }
    },
    {
      "id": "5-3",
      "type": "template-transform",
      "param": {
        "variables": [
          ["topic", ["title", "1"]],
          ["query", ["item", "5"]],
          ["search_json", ["json", "5-2"]],
          ["idx", ["index", "5"]]
        ],
        "template": "You are writing one section of a deep research report.\n\nOverall research topic: {{ topic }}\nThis section corresponds to search query #{{ idx + 1 }}:\n\"{{ query }}\"\n\nYou are given structured search results in JSON form (from Google SERP):\n{{ search_json }}\n\nWrite a well-structured, informative Markdown section based on these results.\n\nStrict requirements:\n- Length: at most 600 words.\n- Use clear Markdown structure: start with a level-2 heading (## ...) that reflects the specific angle of this query.\n- Use short paragraphs, bullet lists or numbered lists where helpful.\n- Synthesize and explain; do not just copy snippets.\n- If there are conflicting views, briefly compare them.\n- Include concrete facts, examples, and key entities when available.\n- Do NOT include raw JSON or long URLs; summarize instead.\n- Do NOT add an overall conclusion for the entire topic; focus only on this angle."
      }
    },
    {
      "id": "5-4",
      "type": "llm",
      "param": {
        "system": "You are a meticulous research writer. Follow the user instructions exactly and produce clean Markdown.",
        "user": "{{#'5-3'.output#}}"
      }
    },
    {
      "id": "6",
      "type": "template-transform",
      "param": {
        "variables": [
          ["sections", ["output", "5"]],
          ["topic", ["title", "1"]]
        ],
        "template": "# Research Report: {{ topic }}\n\n> This report is compiled from multiple web search perspectives. Each section addresses a distinct angle of the topic.\n\n{% for s in sections %}\n{{ s }}\n\n{% endfor %}\n\n---\n\n*End of report.*"
      }
    },
    {
      "id": "7",
      "type": "end",
      "param": {
        "outputs": [
          ["report", ["output", "6"]]
        ]
      }
    }
