# Dify passes `excel_file` as a file-like object/dict depending on runtime.
# We'll handle common structures:

def _get_file_bytes(excel_file):
	"""Return file bytes from the excel_file variable."""
	# If already bytes
	if isinstance(excel_file, (bytes, bytearray)):
		return bytes(excel_file)

	# If it's a dict with `bytes` or `content` key
	if isinstance(excel_file, dict):
		for key in ["bytes", "content", "data"]:
			if key in excel_file and excel_file[key] is not None:
				return excel_file[key]

	# If it's a file-like object
	if hasattr(excel_file, "read"):
		return excel_file.read()

	# Fallback: try str-encoded bytes (not ideal but safe)
	if isinstance(excel_file, str):
		return excel_file.encode("utf-8")

	raise ValueError("Unsupported excel_file format; cannot read bytes.")


