	file_bytes = _get_file_bytes(excel_file)
	buffer = io.BytesIO(file_bytes)

	# Read Excel file using pandas
	# Strategy: if multiple sheets exist, export all; otherwise just the first sheet.
	xl = pd.ExcelFile(buffer)

	if len(xl.sheet_names) == 1:
		# Single sheet -> list of row objects
		df = xl.parse(xl.sheet_names[0])
