        "code": "import json

def main(json_result: str):
	"""Prepare simple ECharts-compatible series and categories from JSON.

	Strategy:
	- If single_sheet: use first numeric column as data, first non-numeric or index as x-axis.
	- If multi_sheet: use the first sheet and same logic.
	- Fallbacks are simple and may need adjustment for specific Excel layouts.
	"""
	obj = json.loads(json_result)

	def build_from_rows(rows):
		if not rows:
			return "", ""
		# Determine columns
		columns = list(rows[0].keys())
		if not columns:
			return "", ""
		# Try to find a numeric column
		numeric_col = None
		for col in columns:
			vals = [r.get(col) for r in rows]
			if any(isinstance(v, (int, float)) for v in vals if v is not None):
				numeric_col = col
				break
		# Fallback: first column
		if numeric_col is None:
			numeric_col = columns[0]
		# Choose x-axis column (prefer a non-numeric column different from numeric_col)
		x_col = None
		for col in columns:
			if col == numeric_col:
				continue
			vals = [r.get(col) for r in rows]
			if any(isinstance(v, str) for v in vals if v is not None):
				x_col = col
				break
		if x_col is None:
			# Fallback: use row index as x-axis
			categories = [str(i) for i in range(len(rows))]
		else:
			categories = [str(r.get(x_col, "")) for r in rows]
		data_vals = []
		for r in rows:
			v = r.get(numeric_col)
			if isinstance(v, (int, float)):
				data_vals.append(v)
			else:
				# Try to coerce to float
				try:
					data_vals.append(float(v))
				except (TypeError, ValueError):
					data_vals.append(0)
		# Join with semicolons for Echarts node
		data_str = ";".join(str(v) for v in data_vals)
		cat_str = ";".join(categories)
		return data_str, cat_str

	type_ = obj.get("type")
	if type_ == "single_sheet":
		sheet_name = obj.get("sheet_name", "Sheet1")
		rows = obj.get("rows", [])
		chart_title = f"Excel sheet: {sheet_name}"
		data_str, cat_str = build_from_rows(rows)
	elif type_ == "multi_sheet":
		sheets = obj.get("sheets", {})
		if sheets:
			first_sheet_name = list(sheets.keys())[0]
			rows = sheets.get(first_sheet_name, [])
			chart_title = f"Excel sheet: {first_sheet_name}"
			data_str, cat_str = build_from_rows(rows)
		else:
			chart_title = "Excel data"
			data_str, cat_str = "", ""
	else:
		chart_title = "Excel data"
		data_str, cat_str = "", ""

	return {
		"chart_title": chart_title,
		"data": data_str,
		"x_axisORcategories": cat_str
	}"
