import json
import urllib.parse
import requests

GITHUB_API_BASE = "https://api.github.com"


def parse_github_url(url: str):
	"""Parse GitHub URL to (owner, repo, ref) where ref is branch/tag/commit or None.
	Supported formats:
	- https://github.com/owner/repo
	- https://github.com/owner/repo/
	- https://github.com/owner/repo/tree/branch
	- https://github.com/owner/repo/tree/branch/path
	- git@github.com:owner/repo.git
	"""
	url = url.strip()
	if not url:
		return None, None, None

	# Handle SSH form: git@github.com:owner/repo.git
	ssh_match = re.match(r"git@github.com:(?P<owner>[^/]+)/(?P<repo>[^.]+)(?:\.git)?", url)
	if ssh_match:
		owner = ssh_match.group("owner")
		repo = ssh_match.group("repo")
		return owner, repo, None

	# Normalize to https URL
	if url.startswith("git://"):
		url = "https://" + url[len("git://"):]

	parsed = urllib.parse.urlparse(url)
	if parsed.netloc not in {"github.com", "www.github.com"}:
		return None, None, None

	parts = [p for p in parsed.path.split("/") if p]
	if len(parts) < 2:
		return None, None, None

	owner = parts[0]
	repo = parts[1]
	# Strip .git suffix if present
	if repo.endswith(".git"):
		repo = repo[:-4]

