        "code": "def main(llm10_text: str):\n\tif '---MERMAID---' in llm10_text:\n\t\tparts = llm10_text.split('---MERMAID---', 1)\n\t\tsummary = parts[0].strip()\n\t\tmermaid = parts[1].strip()\n\telse:\n\t\tsummary = llm10_text.strip()\n\t\tmermaid = ''\n\treturn {\"summary\": summary, \"mindmap_mermaid\": mermaid}"
      }
